"""Error taxonomy for the wvas address-space auditor.

Every failure surfaced by the public API is a :class:`WVasError`. The ``kind``
attribute carries the machine readable classification the diagnostic tooling
switches on, so callers never have to parse an English message.
"""

KINDS = (
    "badarg",          # the caller passed something the API cannot use
    "no-such-process",  # the pid does not name a running process
    "access-denied",   # the process exists but cannot be opened for reading
    "unsupported",     # the platform cannot answer this question at all
    "query-failed",    # the Win32 call itself failed for another reason
)


class WVasError(Exception):
    """A classified failure raised by :mod:`wvas`."""

    def __init__(self, message, kind="query-failed", pid=None):
        super().__init__(message)
        if kind not in KINDS:
            raise ValueError("unknown kind: %r" % (kind,))
        self.kind = kind
        self.pid = pid

    def __str__(self):
        if self.pid is None:
            return super().__str__()
        return "%s (pid=%s)" % (super().__str__(), self.pid)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.
"""

import ctypes
import ctypes.wintypes as wt
import sys

from . import _winapi as w
from .errors import WVasError

# Use a large buffer for NT paths – they can exceed MAX_PATH easily
