_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

# Maximum user-mode address depending on pointer size
if ctypes.sizeof(ctypes.c_void_p) == 8:
    _MAX_ADDRESS = 0x7FFFFFFFFFFFFFFF
else:
    _MAX_ADDRESS = 0x7FFFFFFF


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


def _open_process(pid):
    """Open the target process, raising WVasError with proper classification."""
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)

    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if not handle:
        err = w.last_error()
        if err == w.ERROR_ACCESS_DENIED:
            raise WVasError(
                "access denied opening process", kind="access-denied", pid=pid
            )
        elif err == w.ERROR_INVALID_PARAMETER:
            raise WVasError(
                "process does not exist", kind="no-such-process", pid=pid
            )
        else:
            # Probe with limited access to distinguish "no such process" from
            # "access denied".
            probe = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
            if probe:
                w.CloseHandle(probe)
                raise WVasError(
                    "access denied opening process", kind="access-denied", pid=pid
                )
            else:
                probe_err = w.last_error()
                if probe_err == w.ERROR_ACCESS_DENIED:
                    raise WVasError(
                        "access denied opening process", kind="access-denied", pid=pid
                    )
                else:
                    raise WVasError(
                        "process does not exist", kind="no-such-process", pid=pid
                    )
    return handle


def _parse_multi_string(buf, char_count):
    """Parse a double-null-terminated multi-string from a ctypes wchar buffer.

    Returns a list of individual strings.
    """
    result = []
    current = []
    for i in range(char_count):
        ch = buf[i]
        if ch == '\0':
            if current:
                result.append(''.join(current))
                current = []
            # Check for double null (end of multi-string)
            if i + 1 < char_count and buf[i + 1] == '\0':
                break
        else:
            current.append(ch)
    if current:
        result.append(''.join(current))
    return result


